import { camelCase } from "../../../pull/util.js";
/**
 * Convert a table/column label to the identifier convention used by table
 * authoring and state. Table keys intentionally normalize the whole first
 * word (`ID` -> `id`) and prefix digit-leading keys (`123` -> `f_123`).
 */
export function tableIdentifierKey(input, fallback) {
    const key = camelCase(input.toLowerCase()) || fallback;
    if (key === undefined || key === "")
        return undefined;
    return /^[0-9]/.test(key) ? `f_${key}` : key;
}
/** Pair items with stable, source-ordered, unique table identifier keys. */
export function withTableKeys(items, nameOf, fallback = "item") {
    const used = new Set();
    return items.map((item) => {
        const base = tableIdentifierKey(nameOf(item), fallback) ?? "item";
        let key = base;
        let suffix = 2;
        while (used.has(key))
            key = `${base}${suffix++}`;
        used.add(key);
        return { key, item };
    });
}
